using System;
using CodexLaunch;

static class CoreTests {
 static int passed,failed;
 static LauncherSettings Settings(){return new LauncherSettings {MinimumAnimationSeconds=0,ExpansionSeconds=.28};}
 static WindowSample Window(int id=1,int x=10,bool responsive=true) { return new WindowSample(new IntPtr(id),new PixelRect(x,20,1000,700),responsive); }
 static void Check(bool condition,string message) { if(!condition)throw new Exception(message); }
 static void Test(string name,Action body) { try { body();passed++;Console.WriteLine("PASS "+name); } catch(Exception e) { failed++;Console.WriteLine("FAIL "+name+": "+e.Message); } }
 static void Invalid(Action<LauncherSettings> change) { var s=new LauncherSettings();change(s);bool rejected=false;try{s.Validate();}catch(ArgumentException){rejected=true;}Check(rejected,"invalid setting accepted"); }
 public static int Main() {
  Test("Only the exact installed package is selected",()=>{Check(PackageIdentity.Matches("OpenAI.Codex_2p2nqsd0c76g0","OpenAI.Codex_2p2nqsd0c76g0"),"Codex rejected");Check(!PackageIdentity.Matches("OpenAI.ChatGPT_2p2nqsd0c76g0","OpenAI.Codex_2p2nqsd0c76g0"),"other package accepted");Check(!PackageIdentity.Matches(null,"OpenAI.Codex_2p2nqsd0c76g0"),"missing identity accepted");});
  Test("A newly foregrounded app keeps coverage before the window probe catches up",()=>{var app=new IntPtr(7);var host=new IntPtr(8);Check(WindowPolicy.KeepCover(app,host,IntPtr.Zero,IntPtr.Zero,true,true),"coverage dropped during the detection gap");Check(!WindowPolicy.KeepCover(app,host,IntPtr.Zero,IntPtr.Zero,false,true),"unrelated foreground app remained covered");Check(!WindowPolicy.KeepCover(app,host,IntPtr.Zero,app,true,false),"launching app reclaimed coverage after user switched away");Check(WindowPolicy.KeepCover(host,host,IntPtr.Zero,app,false,false),"returning to overlay did not regain coverage");Check(WindowPolicy.KeepCover(IntPtr.Zero,host,IntPtr.Zero,app,false,true),"transient null foreground dropped coverage");});
  Test("Launch identity rejects arguments and executable paths",()=>{Invalid(s=>s.ApplicationId="explorer.exe /bad");Invalid(s=>s.ApplicationId="OpenAI.Codex_x!App extra");Invalid(s=>s.ApplicationId=null);});
  Test("Timing rejects NaN, infinity, zero and impractical values",()=>{Invalid(s=>s.MaxWaitSeconds=double.NaN);Invalid(s=>s.TransitionSeconds=double.PositiveInfinity);Invalid(s=>s.StableWindowSeconds=0);Invalid(s=>s.MaxWaitSeconds=601);Invalid(s=>s.WindowWidth=10);new LauncherSettings().Validate();});
  Test("Compact splash fits and centers on a negative-coordinate monitor",()=>{var r=WindowLayout.Compact(new PixelRect(-2560,40,2560,1488),960,600,1.5);Check(r.Left==-2000&&r.Top==334&&r.Width==1440&&r.Height==900,"wrong compact placement");var small=WindowLayout.Compact(new PixelRect(0,0,800,500),960,600,2);Check(small.Left==32&&small.Top==25&&small.Width==736&&small.Height==450,"small monitor bounds escaped its work area");});
  Test("Expansion uses the configured duration and finishes before crossfade",()=>{var settings=Settings();settings.ExpansionSeconds=.85;var s=new StartupSession(settings);s.Advance(0,Window());s.Advance(.75,Window());s.Advance(1.175,Window());Check(s.Phase==StartupPhase.Aligning&&Math.Abs(s.AlignmentProgress-.5)<.001&&s.Progress==0,"expansion does not use its own duration");s.Advance(1.61,Window());Check(s.Phase==StartupPhase.Aligning&&s.AlignmentProgress==1,"final bounds did not settle before fade");s.Advance(1.73,Window());Check(s.Phase==StartupPhase.Revealing&&s.Progress==0,"aligned crossfade did not start");Invalid(x=>x.ExpansionSeconds=double.NaN);Invalid(x=>x.ExpansionSeconds=3.1);});
  Test("Reduced motion skips expansion but still paints final bounds",()=>{var settings=Settings();settings.ReducedMotion=true;var s=new StartupSession(settings);s.Advance(0,Window());s.Advance(.75,Window());s.Advance(.8,Window());Check(s.Phase==StartupPhase.Aligning&&s.AlignmentProgress==1,"reduced motion still moves the splash");s.Advance(.88,Window());Check(s.Phase==StartupPhase.Revealing,"reduced motion never revealed the final frame");});
  Test("Transition reaches exact bounds on negative-coordinate monitor",()=>{var a=new PixelRect(50,60,960,600);var b=new PixelRect(-1900,-100,1800,1000);var end=PixelRect.Interpolate(a,b,1);Check(end.Left==-1900&&end.Top==-100&&end.Right==-100&&end.Bottom==900,"wrong final pixels");var mid=PixelRect.Interpolate(a,b,.5);Check(mid.Left==-925&&mid.Top==-20&&mid.Width==1380&&mid.Height==800,"wrong midpoint");Check(PixelRect.Interpolate(a,b,2).Left==-1900,"overshoots");});
  Test("A stable window is aligned and painted before fading",()=>{var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(.74,Window());Check(s.Phase==StartupPhase.Waiting,"too early");s.Advance(.75,Window());Check(s.Phase==StartupPhase.Aligning&&s.Target.Handle==new IntPtr(1),"alignment did not start");s.Advance(1.04,Window());Check(s.Phase==StartupPhase.Aligning&&s.AlignmentProgress==1&&s.Progress==0,"fade began before the new frame could paint");s.Advance(1.16,Window());Check(s.Phase==StartupPhase.Revealing&&s.Progress==0,"fade did not start after alignment");s.Advance(2.22,Window());Check(s.Phase==StartupPhase.Finished&&s.CloseReason=="handoff"&&s.Progress==1,"handoff did not finish");});
  Test("A thirty-second launch continues waiting before handoff",()=>{var s=new StartupSession(Settings());s.Advance(29,null);Check(s.Phase==StartupPhase.Waiting,"ended while app absent");s.Advance(30,Window());s.Advance(30.75,Window());Check(s.Phase==StartupPhase.Aligning,"delayed app never aligned");s.Advance(31.16,Window());Check(s.Phase==StartupPhase.Revealing,"delayed app never shown");});
  Test("Unresponsive and moving windows restart the stability interval",()=>{var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(.7,Window(responsive:false));s.Advance(1,Window());s.Advance(1.5,Window(x:40));s.Advance(2,Window(x:40));Check(s.Phase==StartupPhase.Waiting,"unstable window accepted");s.Advance(2.25,Window(x:40));Check(s.Phase==StartupPhase.Aligning,"stable replacement not accepted");});
  Test("Losing the target during a reveal resumes waiting",()=>{var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(1,Window());s.Advance(1.41,Window());s.Advance(1.5,null);Check(s.Phase==StartupPhase.Waiting&&s.Target==null&&s.Progress==0,"lost target left stale reveal");s.Advance(2,Window(2));s.Advance(2.75,Window(2));Check(s.Phase==StartupPhase.Aligning&&s.Target.Handle==new IntPtr(2),"replacement not accepted");});
  Test("Timeout releases an absent app and stays finished",()=>{var s=new StartupSession(new LauncherSettings());s.Advance(119.9,null);Check(s.Phase==StartupPhase.Waiting,"premature timeout");s.Advance(120,null);Check(s.Phase==StartupPhase.Finished&&s.CloseReason=="timeout","timeout failed");s.Advance(121,Window());Check(s.Phase==StartupPhase.Finished,"finished session restarted");});
  Test("Skip immediately releases a never-ready window",()=>{var s=new StartupSession(new LauncherSettings());s.Advance(.3,Window(responsive:false));s.Skip();Check(s.Phase==StartupPhase.Finished&&s.CloseReason=="skipped","skip waited for readiness");});
  Test("Movement after reveal begins restarts stability",()=>{var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(1,Window());s.Advance(1.41,Window());s.Advance(2.47,Window(x:700));Check(s.Phase==StartupPhase.Waiting,"moving target was handed off");s.Advance(3.22,Window(x:700));Check(s.Phase==StartupPhase.Aligning,"settled target never accepted");});
  Test("Cumulative pixel drift restarts alignment and reveal against fixed bounds",()=>{foreach(bool reveal in new[]{false,true}){var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(.75,Window());double start=.75;if(reveal){s.Advance(1.16,Window());start=1.16;}s.Advance(start+.05,Window(x:11));s.Advance(start+.1,Window(x:12));s.Advance(start+.15,Window(x:13));Check(s.Phase==StartupPhase.Waiting&&s.Target==null,"small per-frame changes accumulated without restarting "+(reveal?"reveal":"alignment"));}});
  Test("Fast launches show the complete greeting before handoff",()=>{var s=new StartupSession(new LauncherSettings());s.Advance(0,Window());s.Advance(.75,Window());Check(s.Phase==StartupPhase.Waiting,"intro cut short");s.Advance(2.49,Window());Check(s.Phase==StartupPhase.Waiting,"greeting cut short");s.Advance(2.5,Window());Check(s.Phase==StartupPhase.Aligning,"ready app waited beyond the intro");});
  Test("Skip still bypasses the minimum introduction",()=>{var s=new StartupSession(new LauncherSettings());s.Advance(.1,Window());s.Skip();Check(s.Phase==StartupPhase.Finished,"skip waited for introduction");});
  Test("Resuming a minimized reveal waits for a fresh stable window",()=>{var s=new StartupSession(Settings());s.Advance(0,Window());s.Advance(1,Window());s.Advance(1.41,Window());s.Advance(1.8,Window());Check(s.Phase==StartupPhase.Revealing&&s.Progress>0,"fixture never entered reveal");s.RestartStability();s.Advance(1.81,Window());s.Advance(2.2,Window());Check(s.Phase==StartupPhase.Waiting&&s.Target==null&&s.Progress==0,"resumed stale handoff without a stable interval");s.Advance(2.57,Window());Check(s.Phase==StartupPhase.Aligning,"resumed window never realigned");s.Skip();s.RestartStability();Check(s.Phase==StartupPhase.Finished,"completed session restarted");});
  Test("A selected smaller window stays selected after foreground changes",()=>{var small=Window(1);var large=Window(2);large.Bounds=new PixelRect(10,20,2000,1200);Check(WindowPolicy.Choose(small,large,new IntPtr(1),IntPtr.Zero).Handle==new IntPtr(1),"selected session switched to larger background window");Check(WindowPolicy.Choose(large,small,IntPtr.Zero,new IntPtr(1)).Handle==new IntPtr(1),"foreground session was not selected initially");});
  Test("Initial minimized window is restored only while launcher owns focus",()=>{var sample=Window();sample.Minimized=true;Check(WindowPolicy.ShouldRestore(sample,new IntPtr(90),new IntPtr(90),IntPtr.Zero,false),"initial requested restore rejected");Check(!WindowPolicy.ShouldRestore(sample,new IntPtr(90),new IntPtr(99),IntPtr.Zero,false),"unrelated foreground app lost focus");Check(!WindowPolicy.ShouldRestore(sample,new IntPtr(90),new IntPtr(90),IntPtr.Zero,true),"user minimization was undone");Check(!WindowPolicy.ShouldRestore(sample,new IntPtr(90),new IntPtr(90),new IntPtr(1),false),"repeated restore");});
  Console.WriteLine("RESULT: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
 }
}
